def apply(p, code):
    """Ubah skenario menjadi butir: kontekstual (atau visual), benar/salah (benar & salah), isian."""
    for si, (tp, long, short, ok, bad, expl, diff, vis) in enumerate(SCEN[code]):
        p.gk = f'sc{code}{si}'
        if vis:
            p.mc(tp, long, ok, bad, expl, diff, 'menerapkan', 'Menerapkan pesan surah', visual=vis)
        else:
            p.ctx(tp, long, ok, bad, expl, diff, 'menerapkan', 'Menerapkan pesan surah')
        if vis:
            continue          # butir bergambar tidak dibuat ulang sebagai benar/salah atau isian tanpa gambar
        p.tf(tp, f'{short} {ok}.', True, expl, diff if diff != 'hard' else 'medium', 'memahami', 'Menerapkan pesan surah')
        p.tf(tp, f'{short} {bad[0]}.', False, f'Salah. {expl}', diff if diff != 'hard' else 'medium', 'memahami', 'Menerapkan pesan surah')
        p.fill(tp, f'Lengkapi: {short} ....', ok, expl, diff, 'menerapkan', 'Menerapkan pesan surah', typ='completion')


def grouping_and_more(p, S, code):
    """Pengelompokan, pengurutan, dan tugas praktik ditulis tangan per surah."""
    p.gk = None
    N = S['name']
    G = {
     'FA': [("sesuai", "kurang sesuai",
             ["membaca bismillah sebelum makan", "mengucap alhamdulillah setelah menerima hadiah", "berdoa memohon jalan yang lurus", "meminta tolong hanya kepada Allah"],
             ["makan tanpa menyebut nama Allah", "tidak bersyukur atas nikmat", "meminta pertolongan kepada jimat", "menyombongkan diri"]),
            ("sesuai", "kurang sesuai",
             ["menghafal Al-Fatihah setiap hari", "membaca Al-Fatihah dalam salat", "bersyukur saat sehat", "berbuat jujur karena yakin ada hari pembalasan"],
             ["menunda belajar membaca Al-Fatihah", "meninggalkan salat", "mengeluh terus-menerus", "berbuat curang karena merasa tidak ketahuan"])],
     'IK': [("sesuai", "kurang sesuai",
             ["meyakini Allah Maha Esa", "memohon pertolongan hanya kepada Allah", "membantu ibu dengan ikhlas", "menjelaskan dengan sopan bahwa Allah tidak punya anak"],
             ["menyembah benda keramat", "meminta pertolongan kepada jimat", "pamer setiap kali berbuat baik", "menganggap ada yang menyamai Allah"]),
            ("sesuai", "kurang sesuai",
             ["membaca Al-Ikhlas sebelum tidur", "bersyukur atas ciptaan Allah", "berdoa kepada Allah ketika butuh bantuan", "belajar menghafal ayat dengan tekun"],
             ["lupa berdoa sebelum tidur", "tidak peduli pada ciptaan Allah", "meminta tolong pada patung", "malas menghafal ayat"])],
     'NS': [("sesuai", "kurang sesuai",
             ["menolak ajakan berbohong", "berlindung kepada Allah saat takut", "beristigfar setelah berbuat salah", "memilih teman yang baik"],
             ["menuruti ajakan membolos", "menjerit ketakutan tanpa berdoa", "mengulangi kata kasar", "ikut meniru teman yang nakal"]),
            ("sesuai", "kurang sesuai",
             ["membaca An-Nas sebelum tidur", "menenangkan diri saat marah", "tidak mudah terpengaruh bisikan jahat", "mengingat bahwa Allah Raja manusia"],
             ["tidur tanpa berdoa", "memukul teman saat marah", "menuruti semua ajakan teman", "melupakan Allah saat sedih"])],
     'FL': [("sesuai", "kurang sesuai",
             ["ikut senang melihat teman juara", "bangun salat Subuh", "berlindung kepada Allah di malam gelap", "mendoakan teman yang mendapat hadiah"],
             ["iri melihat teman juara", "tidur lagi setelah azan Subuh", "berteriak ketakutan tanpa berdoa", "mengejek teman yang mendapat hadiah"]),
            ("sesuai", "kurang sesuai",
             ["bersyukur dengan mainan sendiri", "membaca Al-Falaq sebelum tidur", "tetap tenang saat takut", "meminta bantuan orang dewasa saat takut"],
             ["ingin merebut mainan teman", "tidur tanpa membaca doa", "berteriak dan berlari saat takut", "menyembunyikan rasa takut dan sendirian"])],
    }[code]
    for a, b, ya, tidak in G:
        items = ya + tidak
        random.Random(len(N)).shuffle(items)
        q = f'Kelompokkan sikap berikut ke dalam "sesuai" atau "kurang sesuai" dengan pesan surah {N}: ' + '; '.join(f"'{x}'" for x in items) + '.'
        p.group(4, q, {a: ya, b: tidak}, f'Sikap yang sesuai adalah yang mencerminkan pesan surah {N}.', 'medium', 'mengelompokkan', 'Menerapkan pesan surah')
    O = {
     'FA': [("Urutkan langkah menghafal Al-Fatihah berikut!", ["Mendengarkan contoh bacaan guru", "Menirukan bacaan ayat demi ayat", "Mengulang bacaan setiap hari", "Membaca tanpa melihat tulisan"]),
            ("Urutkan kegiatan sebelum dan saat salat berikut!", ["Berwudu", "Takbiratul ihram", "Membaca Al-Fatihah", "Rukuk"]),
            ("Urutkan kegiatan makan berikut yang sesuai Al-Fatihah!", ["Mencuci tangan", "Membaca bismillah", "Makan dengan tangan kanan", "Mengucap alhamdulillah"])],
     'IK': [("Urutkan langkah menghafal Al-Ikhlas berikut!", ["Mendengarkan contoh bacaan guru", "Menirukan bacaan ayat demi ayat", "Mengulang bacaan setiap hari", "Membaca tanpa melihat tulisan"]),
            ("Urutkan kegiatan sebelum tidur berikut!", ["Menyikat gigi", "Berdoa sebelum tidur", "Membaca Al-Ikhlas", "Tidur dengan tenang"]),
            ("Urutkan cara menjelaskan Al-Ikhlas kepada adik berikut!", ["Membaca ayatnya", "Menyebutkan artinya", "Menjelaskan bahwa Allah Maha Esa", "Mengajak adik meniru bacaan"])],
     'NS': [("Urutkan langkah menghafal An-Nas berikut!", ["Mendengarkan contoh bacaan guru", "Menirukan bacaan ayat demi ayat", "Mengulang bacaan setiap hari", "Membaca tanpa melihat tulisan"]),
            ("Urutkan tindakan saat merasa takut di malam hari berikut!", ["Menenangkan diri", "Membaca ta'awudz", "Membaca An-Nas", "Meminta ditemani orang tua"]),
            ("Urutkan langkah menolak ajakan buruk berikut!", ["Mendengarkan ajakan teman", "Menyadari ajakan itu buruk", "Berlindung kepada Allah", "Menolak dengan sopan"])],
     'FL': [("Urutkan langkah menghafal Al-Falaq berikut!", ["Mendengarkan contoh bacaan guru", "Menirukan bacaan ayat demi ayat", "Mengulang bacaan setiap hari", "Membaca tanpa melihat tulisan"]),
            ("Urutkan kegiatan sebelum tidur berikut!", ["Menyikat gigi", "Berdoa sebelum tidur", "Membaca Al-Falaq", "Tidur dengan tenang"]),
            ("Urutkan sikap saat teman mendapat hadiah berikut!", ["Melihat teman mendapat hadiah", "Menyadari rasa iri muncul", "Berlindung kepada Allah", "Mengucapkan selamat kepada teman"])],
    }[code]
    for q, items in O:
        p.order(4, q if N in q or 'surah' in q.lower() else q + f' (surah {N})', items, 'Urutan yang benar: ' + ' → '.join(items) + '.', 'medium', 'mengurutkan', 'Menerapkan pesan surah')
    P = [
     (4, f'Praktikkan membaca Surah {N} sebelum tidur bersama orang tua, lalu ceritakan kepada guru!', 'Dinilai guru: kebiasaan membaca, ketepatan lafal, dan kemampuan bercerita (skala 1-4).'),
     (4, f'Ceritakan satu contoh sikap dalam kehidupan sehari-hari yang sesuai dengan pesan Surah {N}!', 'Dinilai guru: kesesuaian contoh dengan pesan surah dan kejelasan penyampaian (skala 1-4).'),
     (1, f'Jelaskan dengan bahasamu sendiri apa pesan pokok Surah {N}!', 'Dinilai guru: ketepatan pesan pokok dan kejelasan bahasa (skala 1-4).'),
     (4, f'Ajak seorang teman membaca Surah {N} bersama, lalu saling mengoreksi bacaan!', 'Dinilai guru: ketepatan lafal, kerja sama, dan sikap saling menghargai (skala 1-4).'),
    ]
    for tp, q, r in P:
        p.perf(tp, q, r, f'Murid menunjukkan pemahaman dan pengamalan pesan surah {N}.', 'medium', 'menerapkan', 'Menerapkan pesan surah')
